{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']

    # build distance lookup for unordered pairs
    dist_map = {}
    for n1, n2, d in dist_list:
        key = (n1, n2) if n1 <= n2 else (n2, n1)
        dist_map[key] = d

    # build all edges with mutual reachability distance
    edges = []
    for i, n1 in enumerate(nodes):
        for n2 in nodes[i+1:]:
            key = (n1, n2) if n1 <= n2 else (n2, n1)
            d = dist_map[key]
            w = max(core[n1], core[n2], d)
            edges.append((w, n1, n2))

    # deterministic sort
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for w, n1, n2 in edges:
        if union(n1, n2):
            mst_edges.append([n1, n2, w])
            total_weight += w
        if len(mst_edges) == len(nodes) - 1:
            break

    return {"mst_edges": mst_edges, "total_weight": total_weight}"
}
